package com.phoenix.business.web;import com.phoenix.business.domain.BusinessSettings;import com.phoenix.business.repository.BusinessSettingsRepository;import com.phoenix.business.service.AuditService;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/settings") @RequiredArgsConstructor public class SettingsController {private final BusinessSettingsRepository repo;private final AuditService audit;@GetMapping public BusinessSettings get(){return repo.findById(1L).orElseThrow();}@PutMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN')")public BusinessSettings put(@RequestBody BusinessSettings input){BusinessSettings s=get();s.setGymName(input.getGymName());s.setPhone(input.getPhone());s.setEmail(input.getEmail());s.setAddress(input.getAddress());s.setCurrency(input.getCurrency());s.setTimeZone(input.getTimeZone());s.setLogoUrl(input.getLogoUrl());s.setReceiptFooter(input.getReceiptFooter());s.setTaxIdentifier(input.getTaxIdentifier());s.setReminderDays(input.getReminderDays());s.setAllowMultipleDailyCheckins(input.isAllowMultipleDailyCheckins());s=repo.save(s);audit.record("BUSINESS_SETTINGS_UPDATED","BUSINESS_SETTINGS",1,"Business settings updated");return s;}}
